      document.getElementById('modalArtistImage').src = data.image;
      document.getElementById('modalArtistName').textContent = data.name;
      document.getElementById('modalArtistRole').textContent = data.role;
      document.getElementById('modalArtistBio').textContent = data.bio;
      document.getElementById('modalArtistSession').textContent = data.session;

      modal.classList.add('active');
    }

    function closeArtistModal() {
      const modal = document.getElementById('artistModal');
      modal.classList.remove('active');
    }

    // Close modal on ESC key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeArtistModal();
      }
    });

